#!/usr/bin/env bash
#
# Sandboxed test runner -- generated by `rlsbl scaffold` from the shared
# test-sandbox template. Its knobs live in `.rlsbl/config.json` under
# `test_sandbox` (inner command, default args, toolchain caches, pre-warm
# commands, extra sandbox env); change the config and re-run `rlsbl scaffold`
# rather than editing this file. Hand edits do survive re-scaffolding (three-way
# merge), but they drift from every other repo's runner.
#
# This is the outer layer of the stricttest floor: the plugin's always-on env
# poisoning, credential strip, and socket guard protect every run; this script
# adds the physical isolation a full suite needs. It runs the project's test
# command inside a bubblewrap (bwrap) sandbox where:
#   - the REAL repo is bound read-only (a stray write to the dev tree -> EROFS),
#   - the suite executes in a WRITABLE throwaway copy of the tree (cwd),
#   - TMPDIR is a private tmpfs, HOME is a throwaway tmpfs,
#   - there is NO network (--unshare-net) -- a real push/clone/API call is
#     physically impossible (ENETUNREACH),
#   - declared toolchain caches are served read-only (or as a copy-on-write
#     clone where the tool insists on writing), so the real dev caches are
#     never mutated; ~/.ssh and other credential paths are simply never bound,
#     so they are unreachable.
#
# Portability: this sandbox uses only universally-supported bwrap options
# (--ro-bind/--bind/--tmpfs/--proc/--dev/--symlink/--unshare-*/--die-with-parent/
# --clearenv/--setenv/--chdir). It deliberately avoids --overlay-src/--tmp-overlay
# (overlayfs), which the stock apt bubblewrap on CI runners is built without.
#
# The sandbox exports STRICTTEST_SANDBOX=1, which lifts the stricttest floor's
# bare-run refusal (a bare full-suite run outside the sandbox is a hard error
# when the project sets stricttest_sandbox_required = true).
#
# Usage:
#   scripts/test.sh                 # full suite, configured default args
#   scripts/test.sh -k foo -x       # forward args to the test command
#   scripts/test.sh --selftest      # prove the sandbox invariants
#   scripts/test.sh --sweep-only    # reclaim scratch leaked by killed runs
#
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export REPO_ROOT

# Toolchain caches this project declared (test_sandbox.caches). Everything
# below is keyed off this list, so an ecosystem the project does not use costs
# nothing and requires none of its tools to be installed.
SANDBOX_CACHES="uv go python_user_base"

has_cache() {
  case " ${SANDBOX_CACHES} " in
    *" $1 "*) return 0 ;;
    *) return 1 ;;
  esac
}

BIND_ARGS=(
  --unshare-net --unshare-pid --unshare-ipc --unshare-uts
  --die-with-parent
  --clearenv
  --ro-bind /usr /usr
  --symlink usr/bin /bin
  --symlink usr/sbin /sbin
  --symlink usr/lib /lib
  --symlink usr/lib64 /lib64
  --ro-bind /etc /etc
  --proc /proc
  --dev /dev
  --tmpfs /tmp
  --ro-bind "${REPO_ROOT}" "${REPO_ROOT}"
  --tmpfs /sandbox-home
  --tmpfs /sandbox-tmp
)

ENV_ARGS=(
  --setenv HOME /sandbox-home
  --setenv TMPDIR /sandbox-tmp
  --setenv LANG C.UTF-8
  --setenv STRICTTEST_SANDBOX 1

)

# PATH inside the sandbox. Cache blocks prepend their toolchain directories so
# the in-sandbox tool is the SAME one resolved out here.
SANDBOX_PATH="/usr/local/bin:/usr/bin:/usr/sbin"
prepend_path() { SANDBOX_PATH="$1:${SANDBOX_PATH}"; }

# Optional read-only binds: appended only when the path exists, so the same
# script runs on a dev box and on a bare CI runner without a hard bwrap failure
# on a missing directory.
bind_ro_if_present() {
  [ -d "$1" ] && BIND_ARGS+=(--ro-bind "$1" "$1")
  return 0
}

# --- uv / Python cache -------------------------------------------------------
# uv refuses to run fully read-only even in offline + UV_LINK_MODE=copy mode: it
# touches a root `.lock` and per-bucket `.git` markers, and it caches freshly
# built local wheels into `archive-v0` (verified: EROFS / cross-device rename
# against a read-only cache). Overlayfs (which gave copy-on-write for free) is
# unavailable on stock apt bubblewrap, so the whole cache is cloned into a
# throwaway dir bound writable at the real cache path. The clone uses
# `cp --reflink=auto`: a near-instant copy-on-write clone on btrfs/xfs, a plain
# copy on ext4 CI runners (where the cache holds only warmed deps). It MUST be a
# sibling of the real cache so it lands on the same filesystem -- a tmpfs target
# would defeat reflink and force a full data copy into RAM.
UV_CACHE_COPY=""
if has_cache uv; then
  UV_BIN="$(command -v uv)"
  UV_CACHE="$(uv cache dir)"
  UV_PY_DIR="$(uv python dir)"
  export UV_CACHE
  mkdir -p "${UV_CACHE}"
fi

# --- Go toolchain + module cache --------------------------------------------
# GOTOOLCHAIN=local forces `go` to use exactly the installed toolchain for both
# the pre-warm below and the offline in-sandbox build. With auto-switching, a
# go.mod `go` directive newer than the installed Go makes the outside pre-warm
# silently download a toolchain into the REAL module cache, which the
# fresh-tmpfs GOMODCACHE inside the sandbox cannot re-fetch offline -- so `go`
# breaks in-sandbox and every Go-touching test dies.
if has_cache go; then
  export GOTOOLCHAIN=local
  GOMODCACHE="$(go env GOMODCACHE)"
  GO_DOWNLOAD_CACHE="${GOMODCACHE}/cache/download"
  # GOROOT is bound read-only and put on the sandbox PATH so the in-sandbox `go`
  # is the SAME toolchain resolved here -- not a stale /usr/local/go. On CI,
  # actions/setup-go installs a pinned Go into the hosted tool cache (outside
  # /usr), so hardcoding /usr/local/go would silently run the runner's older
  # preinstalled Go inside the sandbox.
  GOROOT_DIR="$(go env GOROOT)"
  # Host GOPATH/bin holds go-installed toolchain binaries the suite shells out
  # to (linters, gitleaks, and the like).
  GO_BIN_DIR="$(go env GOPATH)/bin"
  export GO_DOWNLOAD_CACHE GOROOT_DIR GO_BIN_DIR
  mkdir -p "${GO_DOWNLOAD_CACHE}"
fi

# --- Python user base --------------------------------------------------------
# Tools installed with `pip install --user` (git-filter-repo and friends) live
# under $HOME/.local; bind that so they keep importing under the throwaway HOME.
if has_cache python_user_base; then
  USERBASE="${HOME}/.local"
  export USERBASE
fi

# --- orphaned scratch sweep --------------------------------------------------
# The runner's scratch dirs (the writable tree copy under TMPDIR, and the uv
# cache clone beside the real cache) are removed by the EXIT trap below. A run
# that dies without running its trap -- SIGKILL, OOM, a closed terminal, a
# cancelled CI job -- leaks a full copy of the repo, and enough of those fill a
# tmpfs /tmp outright. So every run sweeps its OWN leftovers before allocating
# new ones.
#
# Ownership is tracked with a `<scratch-dir>.pid` file kept BESIDE the dir
# rather than inside it, so the working copy of the repo and the
# cloned uv cache stay byte-identical to their sources. A scratch dir is
# orphaned when its owner process is gone (or was never recorded) AND it has not
# been touched for the grace window; the grace window keeps the sweep off a
# concurrent run that has mktemp'd its dir but not yet written the PID file. A
# dir whose owner PID is still alive is left alone until the hard-stale age,
# past which the PID has certainly been recycled -- no sandbox run lasts a day.
SANDBOX_SCRATCH_GRACE_MIN="${SANDBOX_SCRATCH_GRACE_MIN:-5}"
SANDBOX_SCRATCH_HARD_STALE_MIN="${SANDBOX_SCRATCH_HARD_STALE_MIN:-1440}"

scratch_older_than() {
  [ -n "$(find "$1" -maxdepth 0 -mmin "+$2" 2>/dev/null)" ]
}

# Delete scratch paths, retrying once through a recursive chmod. Order matters
# at this scale: a cloned uv cache is ~300k inodes, so a blanket `chmod -R`
# before every removal doubles the syscalls for the common case where nothing
# is write-protected. Only a genuinely locked tree (a test fixture's read-only
# directories) needs the second pass.
scratch_remove() {
  local first="$1"
  rm -rf "$@" 2>/dev/null || true
  if [ -e "${first}" ]; then
    chmod -R u+w "${first}" 2>/dev/null || true
    rm -rf "$@"
  fi
}

sweep_orphaned_scratch() {
  local dir pidfile owner swept=0
  for dir in "$@"; do
    [ -d "${dir}" ] || continue
    pidfile="${dir}.pid"
    owner=""
    if [ -f "${pidfile}" ]; then
      owner="$(cat "${pidfile}" 2>/dev/null || true)"
    fi
    if [ -n "${owner}" ] && kill -0 "${owner}" 2>/dev/null \
       && ! scratch_older_than "${dir}" "${SANDBOX_SCRATCH_HARD_STALE_MIN}"; then
      continue
    fi
    scratch_older_than "${dir}" "${SANDBOX_SCRATCH_GRACE_MIN}" || continue
    # The runner's own transient scratch, never user data: removed outright
    # rather than archived (these are gigabytes of throwaway tree copies).
    scratch_remove "${dir}" "${pidfile}"
    swept=$((swept + 1))
  done
  if [ "${swept}" -gt 0 ]; then
    echo "[sandbox] swept ${swept} orphaned scratch dir(s)" >&2
  fi
  return 0
}

SCRATCH_CANDIDATES=("${TMPDIR:-/tmp}"/test-sandbox-work.*)
if has_cache uv; then
  SCRATCH_CANDIDATES+=("${UV_CACHE}".sandbox.*)
fi
sweep_orphaned_scratch "${SCRATCH_CANDIDATES[@]}"

# `--sweep-only` reclaims orphaned scratch and exits, without pre-warming or
# entering the sandbox. It is how the suite exercises the sweep directly, and
# how a human reclaims space after a run was killed.
if [ "${1:-}" = "--sweep-only" ]; then
  exit 0
fi

# --- local dev overlays (`rlsbl dev sync`) -----------------------------------
# When a sibling checkout has been overlaid onto this project's environment
# (`rlsbl dev sync`, driven by dev-sources.toml.local-only), the sandbox must
# run the suite against THAT source. Otherwise the sandboxed suite keeps testing
# the released registry wheel while the bare venv tests the local tree, and the
# two runs quietly disagree about what is being verified.
#
# The mode is decided by BOTH local-only files -- the declaration, and the
# sentinel `rlsbl dev status` reports on. Neither present: registry mode (CI,
# and every machine without overlays), and the rest of this block is inert.
# Both present and agreeing: overlay mode. Disagreeing: a hard error, never a
# silent fall back to registry wheels. The mode is printed on every run.
#
# Each overlaid checkout is bound READ-ONLY -- exactly what the sandbox already
# does with the repo itself -- so no isolation property is weakened: still no
# network, still a throwaway writable work copy, still nothing writable outside
# it, and the editable install is built offline from the cloned uv cache.
OVERLAY_SPEC=""
if [ -f "${REPO_ROOT}/dev-sources.toml.local-only" ] \
   || [ -f "${REPO_ROOT}/dev-overlays-state.toml.local-only" ]; then
  OVERLAY_SPEC="$(python3 - "${REPO_ROOT}" <<'PYOVERLAY'
import os, sys, tomllib

root = sys.argv[1]
DECL, SENT = "dev-sources.toml.local-only", "dev-overlays-state.toml.local-only"
FIX = ("Run `rlsbl dev sync` (with UV_NO_SYNC=1 exported) to bring the two into "
       "agreement, or delete both files to run against registry wheels.")

def fail(message):
    print(f"[sandbox] dev overlays: {message}\n  {FIX}", file=sys.stderr)
    raise SystemExit(1)

def load(name):
    path = os.path.join(root, name)
    if not os.path.isfile(path):
        return None
    try:
        with open(path, "rb") as handle:
            data = tomllib.load(handle)
    except (tomllib.TOMLDecodeError, OSError) as exc:
        fail(f"{name} could not be read: {exc}")
    entries = data.get("overlay") or []
    if not isinstance(entries, list):
        fail(f"{name}: 'overlay' must be an array of tables.")
    out = {}
    for i, entry in enumerate(entries, start=1):
        if not isinstance(entry, dict):
            fail(f"{name}: [[overlay]] entry #{i} is not a table.")
        package, path_value = entry.get("package"), entry.get("path")
        if not package or not path_value:
            fail(f"{name}: [[overlay]] entry #{i} lacks 'package' or 'path'.")
        if not os.path.isabs(path_value):
            path_value = os.path.join(root, path_value)
        out[package] = os.path.realpath(path_value)
    return out

declared, synced = load(DECL), load(SENT)
if declared is None and synced is None:
    raise SystemExit(0)
if declared is None:
    fail(f"{SENT} records overlays but {DECL} is gone, so what the venv holds "
         "no longer matches any declaration.")
if synced is None:
    fail(f"{DECL} declares overlays but {SENT} does not exist: they were "
         "declared but never installed.")
if set(declared) != set(synced):
    fail(f"{DECL} declares {sorted(declared)} but {SENT} records {sorted(synced)}.")
for package in sorted(declared):
    if declared[package] != synced[package]:
        fail(f"overlay '{package}': declared at {declared[package]} but synced "
             f"from {synced[package]}.")
    if not os.path.isdir(declared[package]):
        fail(f"overlay '{package}': checkout {declared[package]} does not exist.")
    print(f"{package}\t{declared[package]}")
PYOVERLAY
  )" || { echo "[sandbox] FATAL: dev overlays are inconsistent (see above)." >&2; exit 1; }
fi

OVERLAY_SYNC_ARGS=""
OVERLAY_INSTALL=""
OVERLAY_RUN_ARGS=""
OVERLAY_SUMMARY="registry wheels from the lockfile (no dev overlays)"
if [ -n "${OVERLAY_SPEC}" ]; then
  OVERLAY_SYNC_ARGS="--inexact"
  OVERLAY_SUMMARY=""
  while IFS=$'\t' read -r ov_pkg ov_path; do
    [ -n "${ov_pkg}" ] || continue
    BIND_ARGS+=(--ro-bind "${ov_path}" "${ov_path}")
    OVERLAY_SYNC_ARGS="${OVERLAY_SYNC_ARGS} --no-install-package ${ov_pkg}"
    OVERLAY_INSTALL="${OVERLAY_INSTALL}${OVERLAY_INSTALL:+ && }uv pip install --offline -e ${ov_path}"
    OVERLAY_SUMMARY="${OVERLAY_SUMMARY}${OVERLAY_SUMMARY:+, }${ov_pkg} <- ${ov_path} (editable, read-only bind)"
  done <<<"${OVERLAY_SPEC}"
  # `uv run` auto-syncs by default, which would reinstall the locked wheel over
  # the editable install between the overlay step and the test command. This is
  # the same hazard UV_NO_SYNC=1 covers outside the sandbox -- but the env var
  # is NOT usable here: it would be inherited by the test process and by every
  # `uv run` a fixture spawns, so a fixture project's own suite would run
  # against a venv uv was told not to create. The flag scopes it to one command.
  OVERLAY_RUN_ARGS="--no-sync"
fi
# Consumed by the configured inner command (test_sandbox.command). All three are
# empty in registry mode, where the command is then byte-for-byte the
# pure-registry one it has always been.
ENV_ARGS+=(
  --setenv SANDBOX_UV_SYNC_ARGS "${OVERLAY_SYNC_ARGS}"
  --setenv SANDBOX_OVERLAY_INSTALL "${OVERLAY_INSTALL}"
  --setenv SANDBOX_UV_RUN_ARGS "${OVERLAY_RUN_ARGS}"
)

# --- pre-warm (OUTSIDE the sandbox, network allowed) -------------------------
# Config-declared commands (test_sandbox.prewarm), run from the project root
# before the sandbox is entered, so an offline in-sandbox build hits a warm
# cache. They see REPO_ROOT and the resolved cache paths in their environment.
# A non-zero exit aborts the run.
(
  cd "${REPO_ROOT}"
scripts/test-prewarm.sh
)

# --- writable throwaway working copy of the tree (INCLUDING .git; suites need
# real git history). Excludes virtualenvs (absolute paths break on move) and
# disposable caches. ---
WORK="$(mktemp -d "${TMPDIR:-/tmp}/test-sandbox-work.XXXXXX")"
echo $$ >"${WORK}.pid"
if has_cache uv; then
  UV_CACHE_COPY="$(mktemp -d "${UV_CACHE}.sandbox.XXXXXX")"
  echo $$ >"${UV_CACHE_COPY}.pid"
fi
cleanup() {
  scratch_remove "${WORK}" "${WORK}.pid"
  if [ -n "${UV_CACHE_COPY}" ]; then
    scratch_remove "${UV_CACHE_COPY}" "${UV_CACHE_COPY}.pid"
  fi
}
trap cleanup EXIT
if has_cache uv; then
  cp -a --reflink=auto "${UV_CACHE}/." "${UV_CACHE_COPY}/"
fi
rsync -a \
  --exclude '.venv' \
  --exclude '__pycache__' \
  --exclude '.pytest_cache' \
  --exclude '.mypy_cache' \
  --exclude '.ruff_cache' \
  --exclude '.wrangler' \
  --exclude 'node_modules' \
  --exclude '.coverage' \
  "${REPO_ROOT}/" "${WORK}/"

BIND_ARGS+=(--bind "${WORK}" "${WORK}")

if has_cache uv; then
  BIND_ARGS+=(
    --ro-bind "${UV_BIN}" "${UV_BIN}"
    --ro-bind "${UV_PY_DIR}" "${UV_PY_DIR}"
    --bind "${UV_CACHE_COPY}" "${UV_CACHE}"
  )
  ENV_ARGS+=(
    --setenv UV_CACHE_DIR "${UV_CACHE}"
    --setenv UV_PYTHON_INSTALL_DIR "${UV_PY_DIR}"
    --setenv UV_OFFLINE 1
    --setenv UV_LINK_MODE copy
  )
  # Forward UV_PYTHON when set (a CI matrix uses it to pin the interpreter the
  # in-sandbox `uv sync` selects); left unset, uv picks the default one.
  [ -n "${UV_PYTHON:-}" ] && ENV_ARGS+=(--setenv UV_PYTHON "${UV_PYTHON}")
  prepend_path "$(dirname "${UV_BIN}")"
fi

if has_cache go; then
  BIND_ARGS+=(
    --ro-bind "${GO_DOWNLOAD_CACHE}" "${GO_DOWNLOAD_CACHE}"
    --tmpfs /sandbox-gocache
    --tmpfs /sandbox-gomodcache
  )
  bind_ro_if_present "${GO_BIN_DIR}"
  # A GOROOT already under the /usr RO-bind just gets a redundant bind.
  bind_ro_if_present "${GOROOT_DIR}"
  ENV_ARGS+=(
    --setenv GOMODCACHE /sandbox-gomodcache
    --setenv GOCACHE /sandbox-gocache
    --setenv GOPATH /sandbox-home/go
    --setenv GOPROXY "file://${GO_DOWNLOAD_CACHE}"
    --setenv GOSUMDB off
    --setenv GOTOOLCHAIN local
  )
  prepend_path "${GOROOT_DIR}/bin"
  prepend_path "${GO_BIN_DIR}"
fi

if has_cache python_user_base; then
  bind_ro_if_present "${USERBASE}/bin"
  bind_ro_if_present "${USERBASE}/lib"
  ENV_ARGS+=(--setenv PYTHONUSERBASE "${USERBASE}")
  prepend_path "${USERBASE}/bin"
fi

ENV_ARGS+=(--setenv PATH "${SANDBOX_PATH}")

# --- inner command: the configured test command, or the sandbox selftest ---
SANDBOX_COMMAND='uv sync --offline $SANDBOX_UV_SYNC_ARGS && eval "$SANDBOX_OVERLAY_INSTALL" && uv run $SANDBOX_UV_RUN_ARGS --offline pytest'
SANDBOX_DEFAULT_ARGS='-q -n auto'

# An active overlay is only honoured if the configured command consumes the
# three variables the block above sets. A command that ignores them would bind
# the checkout read-only, print "overlay", and then run the suite against the
# locked registry wheel anyway -- a preview that lies. Refuse instead.
if [ -n "${OVERLAY_SPEC}" ]; then
  for ov_var in SANDBOX_UV_SYNC_ARGS SANDBOX_OVERLAY_INSTALL SANDBOX_UV_RUN_ARGS; do
    case "${SANDBOX_COMMAND}" in
      *"\$${ov_var}"*) ;;
      *)
        {
          echo "[sandbox] FATAL: dev overlays are active, but test_sandbox.command"
          echo "  does not reference \$${ov_var}, so the overlay would be bound and"
          echo "  then ignored. Set the command in .rlsbl/config.json to:"
          echo "    uv sync --offline \$SANDBOX_UV_SYNC_ARGS && eval \"\$SANDBOX_OVERLAY_INSTALL\" && uv run \$SANDBOX_UV_RUN_ARGS --offline <test command>"
          echo "  and re-run \`rlsbl scaffold\`."
        } >&2
        exit 1
        ;;
    esac
  done
fi

if [ "${1:-}" = "--selftest" ]; then
  INNER='
    set -u
    fail=0
    echo "[selftest] real repo path should be read-only:"
    if touch "'"${REPO_ROOT}"'/.sandbox-probe" 2>probe.err; then
      echo "  FAIL: wrote to the real repo (expected EROFS)"; fail=1
    else
      echo "  OK: $(cat probe.err)"
    fi
    echo "[selftest] external network should be dead:"
    if python3 - <<PY 2>net.err; then
import socket
s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.settimeout(3)
s.connect(("1.1.1.1", 443))
PY
      echo "  FAIL: opened an external TCP connection (expected no network)"; fail=1
    else
      echo "  OK: $(tr "\n" " " <net.err | tail -c 200)"
    fi
    exit $fail
  '
else
  if [ "$#" -eq 0 ]; then
    RUN_ARGS="${SANDBOX_DEFAULT_ARGS}"
  else
    RUN_ARGS="$*"
  fi
  INNER="${SANDBOX_COMMAND} ${RUN_ARGS}"
fi

echo "[sandbox] bwrap: real repo RO, writable copy=${WORK}, no network, TMPDIR=tmpfs, caches=${SANDBOX_CACHES:-none}" >&2

echo "[sandbox] dependency source: ${OVERLAY_SUMMARY}" >&2

# --- preflight: the two known sandbox-SETUP failures (distinct from test
# failures) surface as a non-zero bwrap exit at startup, before the inner
# command ever runs. Probe them with a trivial `--unshare-net` sandbox so we
# can emit a targeted diagnostic instead of a bare bwrap error line. ---
PROBE_ERR="$(mktemp "${TMPDIR:-/tmp}/bwrap-probe.XXXXXX")"
if ! bwrap \
      --unshare-net --unshare-pid --die-with-parent \
      --ro-bind /usr /usr \
      --symlink usr/bin /bin --symlink usr/lib /lib --symlink usr/lib64 /lib64 \
      --proc /proc --dev /dev \
      true 2>"${PROBE_ERR}"; then
  {
    echo "[sandbox] FATAL: bwrap could not create the --unshare-net sandbox."
    echo "  Two known causes on CI runners (esp. Ubuntu 24.04):"
    echo "    1. bubblewrap < 0.10 cannot configure loopback under --unshare-net"
    echo "       ('loopback: Failed RTM_NEWADDR: Operation not permitted')."
    echo "       Fix: use bubblewrap >= 0.11.0."
    echo "    2. Ubuntu 24.04 restricts unprivileged user namespaces to"
    echo "       AppArmor-profiled binaries; a source-built bwrap has no profile."
    echo "       Fix: sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0"
    echo "  bwrap version: $(bwrap --version 2>/dev/null || echo unknown)"
    echo "  bwrap stderr : $(tr '\n' ' ' <"${PROBE_ERR}")"
  } >&2
  rm -f "${PROBE_ERR}"
  exit 1
fi
rm -f "${PROBE_ERR}"

# Deliberately NOT `exec`: exec replaces this shell, and with it the EXIT
# trap, so the scratch dirs survived every run -- successful ones included --
# not merely killed ones. bwrap runs as a child and its status is forwarded
# after cleanup. Signals still reach it: it shares this foreground process
# group and carries --die-with-parent.
status=0
bwrap \
  "${BIND_ARGS[@]}" \
  "${ENV_ARGS[@]}" \
  --chdir "${WORK}" \
  bash -c "${INNER}" || status=$?
exit "${status}"
